import{_ as t,o as a,c as i,a6 as s}from"./chunks/framework.BHBQfcoO.js";const g=JSON.parse('{"title":"Device Identity Manager","description":"","frontmatter":{},"headers":[],"relativePath":"architecture/subsystems/device-identity.md","filePath":"architecture/subsystems/device-identity.md"}'),d={name:"architecture/subsystems/device-identity.md"};function n(r,e,o,l,h,c){return a(),i("div",null,[...e[0]||(e[0]=[s(`<h1 id="device-identity-manager" tabindex="-1">Device Identity Manager <a class="header-anchor" href="#device-identity-manager" aria-label="Permalink to &quot;Device Identity Manager&quot;">​</a></h1><blockquote><p><strong>Subsystem</strong>: <code>window.lcards.core.deviceIdentityManager</code><strong>Class</strong>: <code>DeviceIdentityManager</code> (<code>src/core/services/DeviceIdentityManager.js</code>)</p></blockquote><hr><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p><code>DeviceIdentityManager</code> provides a <strong>stable, human-labelled identity</strong> for the current browser profile. This identity is used as the key for device-scoped settings in the <a href="./scoped-settings.html"><code>ScopedSettingsService</code></a> waterfall.</p><h3 id="what-makes-a-device" tabindex="-1">What makes a &quot;device&quot;? <a class="header-anchor" href="#what-makes-a-device" aria-label="Permalink to &quot;What makes a &quot;device&quot;?&quot;">​</a></h3><p>A <strong>device</strong> in LCARdS is a specific browser profile on a specific machine, not the physical hardware. Two different Chrome profiles on the same laptop are two different devices. This matches how browser_mod and similar integrations handle device identity.</p><table tabindex="0"><thead><tr><th>Concept</th><th>Implementation</th></tr></thead><tbody><tr><td>Stable ID</td><td>UUID (<code>crypto.randomUUID()</code>) stored in <code>localStorage[&#39;lcards_device_id&#39;]</code></td></tr><tr><td>Display name</td><td>User-settable string; auto-seeded from user-agent on first boot</td></tr><tr><td>Backend registration</td><td>Heartbeat WS call at startup (after IntegrationService probe)</td></tr><tr><td>Override at launch</td><td><code>?lcards_device=&lt;name&gt;</code> URL parameter</td></tr></tbody></table><hr><h2 id="api" tabindex="-1">API <a class="header-anchor" href="#api" aria-label="Permalink to &quot;API&quot;">​</a></h2><div class="language-javascript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> dim</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> window.lcards.core.deviceIdentityManager;</span></span></code></pre></div><h3 id="properties" tabindex="-1">Properties <a class="header-anchor" href="#properties" aria-label="Permalink to &quot;Properties&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Property</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>dim.deviceId</code></td><td><code>string</code></td><td>Stable UUID for this browser profile</td></tr><tr><td><code>dim.displayName</code></td><td><code>string</code></td><td>Human-readable name</td></tr><tr><td><code>dim.lastSeen</code></td><td><code>string|null</code></td><td>ISO timestamp of last heartbeat, or null</td></tr><tr><td><code>dim.userAgent</code></td><td><code>string</code></td><td><code>navigator.userAgent</code></td></tr></tbody></table><h3 id="methods" tabindex="-1">Methods <a class="header-anchor" href="#methods" aria-label="Permalink to &quot;Methods&quot;">​</a></h3><div class="language-javascript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// Rename this device (persists to backend immediately)</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">await</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> dim.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">setDisplayName</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;Kitchen Tablet&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// Explicit heartbeat (called automatically at startup - you rarely need this)</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">await</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> dim.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">registerHeartbeat</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">();</span></span></code></pre></div><hr><h2 id="first-boot-behaviour" tabindex="-1">First-Boot Behaviour <a class="header-anchor" href="#first-boot-behaviour" aria-label="Permalink to &quot;First-Boot Behaviour&quot;">​</a></h2><p>On the first HASS update, <code>_init()</code> runs once and:</p><ol><li><strong>Loads or creates UUID</strong>: checks <code>localStorage[&#39;lcards_device_id&#39;]</code>; generates a v4 UUID if absent.</li><li><strong>Applies <code>?lcards_device=</code> URL parameter</strong>: if present, sets the display name <em>and</em> persists it to localStorage.</li><li><strong>Seeds display name</strong>: if no display name is set, auto-derives one from the user-agent string (e.g. <code>Chrome-Android</code>, <code>Safari-iPhone</code>, <code>Firefox-Linux</code>).</li><li><strong>Registers heartbeat</strong>: after <code>IntegrationService.onReady()</code> resolves, sends display name, ISO timestamp, and user-agent to <code>_device_&lt;uuid&gt;</code> in backend storage.</li></ol><hr><h2 id="naming-convention-url-parameter" tabindex="-1">Naming Convention: URL Parameter <a class="header-anchor" href="#naming-convention-url-parameter" aria-label="Permalink to &quot;Naming Convention: URL Parameter&quot;">​</a></h2><p>Following the <code>?lcards_log_level=debug</code> convention, device names are set via:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://your-ha-instance/lovelace/?lcards_device=Kitchen+Tablet</span></span></code></pre></div><p>The name is persisted to localStorage on first boot so the URL parameter only needs to be used once per browser profile. Subsequent navigations without the parameter retain the set name.</p><hr><h2 id="auto-seeded-display-names" tabindex="-1">Auto-Seeded Display Names <a class="header-anchor" href="#auto-seeded-display-names" aria-label="Permalink to &quot;Auto-Seeded Display Names&quot;">​</a></h2><p>When no display name has been set, <code>_seedDisplayName()</code> produces a readable label from <code>navigator.userAgent</code>:</p><table tabindex="0"><thead><tr><th>User-agent pattern</th><th>Auto-seed</th></tr></thead><tbody><tr><td>Chrome + Android</td><td><code>Chrome-Android</code></td></tr><tr><td>Chrome + Windows</td><td><code>Chrome-Windows</code></td></tr><tr><td>Safari + iPhone</td><td><code>Safari-iPhone</code></td></tr><tr><td>Firefox + Linux</td><td><code>Firefox-Linux</code></td></tr><tr><td>…</td><td>(two-segment <code>Browser-OS</code> pattern)</td></tr></tbody></table><hr><h2 id="admin-panel" tabindex="-1">Admin Panel <a class="header-anchor" href="#admin-panel" aria-label="Permalink to &quot;Admin Panel&quot;">​</a></h2><p>Admins can view and manage all registered devices from the <strong>LCARdS Config Panel → Users &amp; Devices</strong> tab:</p><ul><li>List all devices with display name and last-seen timestamp</li><li>Rename any device</li><li>Delete a device&#39;s entire record from the backend</li></ul><p>Non-admin users can update their own device&#39;s display name from the same tab&#39;s <strong>This Device</strong> section.</p><hr><h2 id="backend-storage" tabindex="-1">Backend Storage <a class="header-anchor" href="#backend-storage" aria-label="Permalink to &quot;Backend Storage&quot;">​</a></h2><p>Device data is stored as a flat key <code>_device_&lt;uuid&gt;</code> in the LCARdS integration store:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;display_name&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Kitchen Tablet&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;last_seen&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:    </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;2026-04-12T09:21:05.000Z&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;user_agent&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:   </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Mozilla/5.0 (Linux; Android …)&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>Any device-scoped settings are stored as additional keys in the same object via <code>ScopedSettingsService.write()</code>.</p><hr><h2 id="see-also" tabindex="-1">See Also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See Also&quot;">​</a></h2><ul><li><a href="./scoped-settings.html">Scoped Settings Service</a></li><li><a href="./integration-service.html">Integration Service</a></li></ul>`,41)])])}const k=t(d,[["render",n]]);export{g as __pageData,k as default};
